"""Harness-only compat shim: restore numpy<1.20 scalar aliases removed in
numpy 1.24 for the 2019-era sklearn source. Lives outside the repo."""
try:
    import numpy as _np
    for _name, _target in [
        ("float", float), ("int", int), ("bool", bool),
        ("object", object), ("str", str), ("complex", complex),
        ("long", int), ("unicode", str),
    ]:
        if not hasattr(_np, _name):
            setattr(_np, _name, _target)
except Exception:
    pass

